student_answer:
ios :: in serve para ler abrir ficheiros de leitura; ios :: out serve para ler abrir ficheiros de escrita; 

int main() {

 ifstream ficheiro_leitura("dados.txt");

 if (ficheiro_leitura.is_open()) {
 string linha;
 while (getline(ficheiro_leitura, linha)) {
 cout << linha << endl;
 }
 ficheiro_leitura.close();
 } else {
 cout << "Não foi possível abrir o ficheiro." << endl;
 }

 ofstream ficheiro_escrita("saida.txt");

 if (ficheiro_escrita.is_open()) {
 ficheiro_escrita << "Esta é uma linha escrita no ficheiro." << endl;
 ficheiro_escrita.close();
 } else {
 cout << "Não foi possível abrir o ficheiro para escrita." << endl;
 }

 return 0;

