#include 
using namespace std;

struct Morada{
 string rua;
 int codPost;
 string localidade;
}

struct Pessoa{
 int id;
 string nome;
 string dataNasc;
 Morada morada;
}

Pessoa inserirPessoa(int id, string nome, string dataNasc, string rua, int codPost, string localidade){
Pessoa *p = new Pessoa();
p.id = id;
p.nome = nome;
p.dataNasc = dataNasc;
p.morada.rua = rua;
p.morada.codPost = codPost;
p.morada.localidade = localidade;

return p;
}

int main(){
int nPessoas, nPessoasReg = 0;
cout >nPessoas;
Pessoas *pessoas = new Pessoas[nPessoas];
for (int i = 0; i >id;
cout > nome;
cout >dataNasc;
cout >rua;
cout >codPost;
cout >localidade;

pessoas[i] = inserirPessoa(id, nome, dataNasc, rua, codPost, localidade);
nPessoasReg++;
}
cout << "Foram registadas <<nPessoasReg<< " Pessoas!"<<endl;
delete pessoas;
}

